import { useMemo, useState } from "react";
import lookup from "../data/lookup";

/**
 * useCalculator
 * Encapsulates all lookup and calculation logic per README_TEAM specs.
 */
export function useCalculator() {
  const [title, setTitle] = useState("");
  const [size, setSize] = useState("");
  const [quantity, setQuantity] = useState(1);
  const [result, setResult] = useState(null); // null | { status, ... }

  // Unique sorted product titles
  const titles = useMemo(() => {
    const set = new Set(lookup.map((r) => r.title));
    return [...set].sort();
  }, []);

  // Available sizes for selected title
  const sizes = useMemo(() => {
    if (!title) return [];
    const set = new Set(
      lookup.filter((r) => r.title === title).map((r) => r.size)
    );
    return [...set].sort();
  }, [title]);

  function handleTitleChange(newTitle) {
    setTitle(newTitle);
    setSize("");
    setResult(null);
  }

  function handleSizeChange(newSize) {
    setSize(newSize);
    setResult(null);
  }

  function calculate() {
    if (!title || !size || quantity < 1) return;

    const row = lookup.find(
      (r) => r.title === title && r.size === size
    );

    if (!row) {
      setResult({ status: "not_found" });
      return;
    }

    const total = parseFloat((row.E_total_kg_co2e * quantity).toFixed(4));
    const avoided =
      row.pathway === "B"
        ? parseFloat((row.avoided_kg_co2e * quantity).toFixed(4))
        : 0;

    setResult({
      status: "ok",
      title: row.title,
      size: row.size,
      quantity,
      pathway: row.pathway,
      product_type: row.product_type,
      dye_type: row.dye_type,
      natural_dye: row.natural_dye,
      total_kg: total,
      avoided_kg: avoided,
      per_unit_kg: row.E_total_kg_co2e,
      breakdown: {
        transport: row.E_transport,
        electricity: row.E_electricity,
        water: row.E_water,
        tailoring: row.E_tailoring,
      },
    });
  }

  function reset() {
    setTitle("");
    setSize("");
    setQuantity(1);
    setResult(null);
  }

  return {
    title, setTitle: handleTitleChange,
    size, setSize: handleSizeChange,
    quantity, setQuantity,
    titles, sizes,
    result,
    calculate,
    reset,
  };
}
